-- =====================================================================
-- Sample test drives, for showing the Test Drives section.
--
-- 436 made-up drives from 01 Aug to 15 Nov 2026 on the five demo cars, with
-- the sales executives' names, booked through the AI agent, the sales desk and
-- walk-ins: drives done, missed and called off up to 06 Oct, drives booked
-- after it, and enquiries still waiting for a time.
-- (203 attended, 156 booked, 32 cancelled, 31 no_show, 14 requested.)
--
-- Every row is sample = true. A sample drive holds no slot: a real customer
-- can still be booked into it, by the agent or on the board, and the board
-- shows the real drive. Run db/test_drives.sql first (it adds the column).
-- Re-runnable: the samples are cleared and made again.
--
-- To remove them all:
--     DELETE FROM dsr.test_drive_booking WHERE sample;
-- =====================================================================

DELETE FROM dsr.test_drive_booking WHERE sample;


SELECT status, count(*) AS drives FROM dsr.test_drive_booking WHERE sample GROUP BY status ORDER BY status;
